import{_ as t}from"./chunks/screenshot-placeholder.DKyzYp9t.js";import{_ as i,o as n,c as l,a2 as e}from"./chunks/framework.CCtxZRER.js";const b=JSON.parse('{"title":"Mencatat Hasil Hitung Fisik","description":"Mengisi lembar hitung, menghitung selisih, dan menghitung akurasi stok.","frontmatter":{"title":"Mencatat Hasil Hitung Fisik","description":"Mengisi lembar hitung, menghitung selisih, dan menghitung akurasi stok.","status":"draf","dasar":"materi presentasi Gudang Teknik (slide 12–13) dan praktik umum stock opname","diperbarui":"2026-10-13T00:00:00.000Z","kategori":"Tutorial","tingkat":"Pemula","sumber":["ppt-gudang-teknik"],"kata_kunci":["tutorial","stock opname","hitung fisik","lembar hitung","selisih","akurasi stok","stock accuracy"]},"headers":[],"relativePath":"tutorial/hitung-fisik.md","filePath":"tutorial/hitung-fisik.md"}'),s={name:"tutorial/hitung-fisik.md"};function d(r,a,u,o,g,h){return n(),l("div",null,[...a[0]||(a[0]=[e('<h1 id="mencatat-hasil-hitung-fisik" tabindex="-1">Mencatat Hasil Hitung Fisik <a class="header-anchor" href="#mencatat-hasil-hitung-fisik" aria-label="Permalink to &quot;Mencatat Hasil Hitung Fisik&quot;">​</a></h1><p class="lead">Latihan mengisi lembar hitung stock opname, menghitung selisih, lalu menghitung akurasi stok.</p><div class="tip custom-block"><p class="custom-block-title">Sebelum mulai</p><ul><li><strong>Setelah latihan ini, kamu bisa</strong> mencatat hasil hitung, menghitung selisih, dan menghitung akurasi stok.</li><li><strong>Tingkat:</strong> Pemula, sekitar 25 menit.</li><li><strong>Baca dulu:</strong> <a href="/WareHouse/alur-kerja/stock-opname">Alur Stock Opname</a>.</li><li><strong>Siapkan:</strong> lembar hitung (format dari pembimbing), alat tulis, kalkulator.</li></ul></div><h2 id="langkah" tabindex="-1">Langkah <a class="header-anchor" href="#langkah" aria-label="Permalink to &quot;Langkah&quot;">​</a></h2><ol><li><strong>Tulis kode, nama, dan satuan</strong> setiap barang di lembar hitung.</li><li><strong>Hitung barang fisik</strong> di lokasinya, lalu tulis jumlahnya. Tulis apa adanya, tanpa melihat angka catatan lebih dulu jika memungkinkan.</li><li><strong>Salin jumlah di catatan</strong> setelah selesai menghitung.</li><li><strong>Hitung selisih</strong>: selisih = fisik − catatan. <ul><li>Selisih <strong>minus</strong> berarti barang fisik <strong>lebih sedikit</strong> dari catatan.</li><li>Selisih <strong>plus</strong> berarti barang fisik <strong>lebih banyak</strong> dari catatan.</li></ul></li><li><strong>Hitung ulang</strong> setiap baris yang selisihnya bukan nol.</li><li><strong>Hitung akurasi stok</strong>: jumlah item yang cocok ÷ jumlah item yang dihitung × 100.</li><li><strong>Serahkan lembar hitung</strong> ke pembimbing. Jangan mengubah catatan stok sendiri.</li></ol><h2 id="contoh-dengan-data-latihan" tabindex="-1">Contoh dengan data latihan <a class="header-anchor" href="#contoh-dengan-data-latihan" aria-label="Permalink to &quot;Contoh dengan data latihan&quot;">​</a></h2><table class="tabel-tumpuk" tabindex="0"><thead><tr><th>Kode (latihan)</th><th>Material</th><th>Satuan</th><th>Catatan</th><th>Fisik</th><th>Selisih</th></tr></thead><tbody><tr><td data-label="Kode (latihan)"><code>CTH-MEC-001</code></td><td data-label="Material">Bearing 6205-2RS</td><td data-label="Satuan">pcs</td><td data-label="Catatan">24</td><td data-label="Fisik">24</td><td data-label="Selisih">0</td></tr><tr><td data-label="Kode (latihan)"><code>CTH-FAS-014</code></td><td data-label="Material">Baut M12 × 50</td><td data-label="Satuan">pcs</td><td data-label="Catatan">150</td><td data-label="Fisik">146</td><td data-label="Selisih">−4</td></tr><tr><td data-label="Kode (latihan)"><code>CTH-CON-003</code></td><td data-label="Material">Grease 0,5 kg</td><td data-label="Satuan">kaleng</td><td data-label="Catatan">12</td><td data-label="Fisik">12</td><td data-label="Selisih">0</td></tr><tr><td data-label="Kode (latihan)"><code>CTH-PPE-007</code></td><td data-label="Material">Sarung tangan kerja</td><td data-label="Satuan">pasang</td><td data-label="Catatan">40</td><td data-label="Fisik">42</td><td data-label="Selisih">+2</td></tr><tr><td data-label="Kode (latihan)"><code>CTH-ELE-021</code></td><td data-label="Material">Fuse 10 A</td><td data-label="Satuan">pcs</td><td data-label="Catatan">30</td><td data-label="Fisik">30</td><td data-label="Selisih">0</td></tr></tbody></table><p>Item yang cocok: 3 dari 5.</p><blockquote><p><strong>Akurasi stok = 3 ÷ 5 × 100 = 60%</strong></p></blockquote><p>Dua baris yang selisih perlu ditelusuri:</p><ul><li><strong>Baut −4.</strong> Mungkin ada pengeluaran yang belum dicatat, atau baut tersimpan di lokasi lain.</li><li><strong>Sarung tangan +2.</strong> Mungkin ada penerimaan yang belum dicatat, atau barang yang dikembalikan user tanpa catatan.</li></ul><figure><p><img src="'+t+'" alt="Placeholder: contoh lembar hitung stock opname"></p><figcaption>Placeholder. Ganti dengan contoh lembar hitung resmi (tanpa data asli).</figcaption></figure><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h2><ul><li>Hitung barang kecil per kelompok, misalnya per 10, agar tidak kehilangan hitungan.</li><li>Catat barang rusak di kolom keterangan, jangan digabung dengan barang yang layak pakai.</li></ul><h2 id="kesalahan-umum" tabindex="-1">Kesalahan umum <a class="header-anchor" href="#kesalahan-umum" aria-label="Permalink to &quot;Kesalahan umum&quot;">​</a></h2><ul><li>Membalik rumus selisih menjadi catatan − fisik, sehingga tanda plus dan minus tertukar.</li><li>Menghitung akurasi dari jumlah unit, bukan jumlah item.</li></ul><h2 id="hasil-yang-diharapkan" tabindex="-1">Hasil yang diharapkan <a class="header-anchor" href="#hasil-yang-diharapkan" aria-label="Permalink to &quot;Hasil yang diharapkan&quot;">​</a></h2><p>Lembar hitung yang lengkap, selisih per item dengan tanda yang benar, angka akurasi stok, dan daftar item yang perlu ditelusuri.</p>',18)])])}const c=i(s,[["render",d]]);export{b as __pageData,c as default};
